                    b.FlatAppearance.BorderColor = DesignSystem.C_DestaqueHover;
                }
                else
                {
                    b.BackColor = DesignSystem.C_Superficie;
                    b.ForeColor = DesignSystem.C_TextoPrimario;
                    b.FlatAppearance.BorderColor = DesignSystem.C_Borda;
                }
            };

            styleButton(copyButton, "Copiar", false);
            styleButton(exportButton, "Exportar", false);
            styleButton(closeButton, "Fechar", true);
            closeButton.DialogResult = DialogResult.OK;

            copyButton.Click += delegate
            {
                try { Clipboard.SetText(textBox.Text); }
                catch { MessageBox.Show("Nao foi possivel copiar."); }
            };

            exportButton.Click += delegate
            {
                try
                {
                    using (var sfd = new SaveFileDialog())
                    {
                        sfd.Filter = "Texto (*.txt)|*.txt|CSV (*.csv)|*.csv|Todos (*.*)|*.*";
                        sfd.DefaultExt = "txt";
                        sfd.FileName = string.Format("TeklaOS_Relatorio_{0}", DateTime.Now.ToString("yyyyMMdd_HHmm"));
                        if (sfd.ShowDialog() == DialogResult.OK)
                        {
                            File.WriteAllText(sfd.FileName, textBox.Text, Encoding.UTF8);
                            MessageBox.Show("Arquivo salvo.", "Exportar", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                    }
                }
                catch (Exception exFile)
                {
                    MessageBox.Show("Erro ao salvar: " + exFile.Message);
                }
            };

            Action refreshFilter = delegate
            {
                int matches;
                string filtered = FilterReportLines(reportText, txtFilter.Text, out matches);
                textBox.Clear();
                AppendColoredText(textBox, filtered);

                if (string.IsNullOrWhiteSpace(txtFilter.Text))
                {
                    lblFilterStatus.Text = "";
                }
                else if (matches == 0)
                {
                    lblFilterStatus.Text = "0 resultados";
                    lblFilterStatus.ForeColor = DesignSystem.C_Erro;
                }
                else
                {
                    lblFilterStatus.Text = string.Format("{0} linha(s)", matches);
                    lblFilterStatus.ForeColor = DesignSystem.C_TextoSecundario;
                }
            };

            txtFilter.TextChanged += delegate { refreshFilter(); };

            txtFilter.KeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.KeyCode == Keys.Escape)
                {
                    txtFilter.Text = string.Empty;
                    e.SuppressKeyPress = true;
                }
            };

            buttonPanel.FlowDirection = FlowDirection.RightToLeft;
            buttonPanel.Dock = DockStyle.Fill;
            buttonPanel.AutoSize = true;
            buttonPanel.Padding = new Padding(0, 6, 0, 0);
            buttonPanel.WrapContents = false;
            buttonPanel.Controls.Add(closeButton);
            buttonPanel.Controls.Add(exportButton);
            buttonPanel.Controls.Add(copyButton);

            panel.Dock = DockStyle.Fill;
            panel.ColumnCount = 1;
            panel.RowCount = 3;
            panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            panel.RowStyles.Add(new RowStyle(SizeType.Percent, 100F));
            panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            panel.Padding = new Padding(12);
            panel.Controls.Add(filterPanel, 0, 0);
            panel.Controls.Add(textBox, 0, 1);
            panel.Controls.Add(buttonPanel, 0, 2);

            form.Controls.Add(panel);
            form.AcceptButton = closeButton;
            form.CancelButton = closeButton;

            refreshFilter();
            form.ShowDialog();
        }
    }

    private static string FilterReportLines(string source, string query, out int matches)
    {
        matches = 0;
        if (string.IsNullOrEmpty(source)) return string.Empty;

        string normalized = source.Replace("\r\n", "\n");
        string[] lines = normalized.Split('\n');

        if (string.IsNullOrWhiteSpace(query))
        {
            matches = lines.Length;
            return source;
        }

        string search = query.Trim();
        var sb = new StringBuilder();
        for (int i = 0; i < lines.Length; i++)
        {
            string line = lines[i];
            if (line.IndexOf(search, StringComparison.OrdinalIgnoreCase) < 0) continue;
            if (matches > 0) sb.AppendLine();
            sb.Append(line);
            matches++;
        }

        return sb.ToString();
    }

    private static void AppendColoredText(RichTextBox box, string text)
    {
        if (string.IsNullOrEmpty(text)) return;

        string normalized = text.Replace("\r\n", "\n");
        string[] lines = normalized.Split('\n');
        for (int i = 0; i < lines.Length; i++)
        {
            string line = lines[i];
            Color color = DesignSystem.C_TextoPrimario;

            if (line.StartsWith("[OK]"))
            {
                color = DesignSystem.C_Sucesso;
            }
            else if (line.StartsWith("[X]"))
            {
                color = DesignSystem.C_Erro;
            }
            else if (line.StartsWith("[~]"))
            {
                color = DesignSystem.C_Atencao;
            }
            else if (line.StartsWith("==="))
            {
                color = DesignSystem.C_Cabecalho;
            }
            else if (line.Contains("APROVADO"))
            {
                color = DesignSystem.C_Sucesso;
            }
            else if (line.Contains("REPROVADO"))
            {
                color = DesignSystem.C_Erro;
            }

            box.SelectionStart = box.TextLength;
            box.SelectionLength = 0;
            box.SelectionColor = color;
            box.AppendText(line);
            if (i < lines.Length - 1)
            {
                box.AppendText(Environment.NewLine);
            }
        }

        box.SelectionColor = box.ForeColor;
    }
}


internal static class TeklaCommands
{
    public static void RunModelRepair(Tekla.Macros.Runtime.IMacroRuntime runtime)
    {
        if (runtime == null)
        {
            MessageBox.Show("Nao foi possivel acessar o runtime da macro.");
            return;
        }

        Tekla.Macros.Akit.IAkitScriptHost akit = runtime.Get<Tekla.Macros.Akit.IAkitScriptHost>();
        if (akit == null)
        {
            MessageBox.Show("Nao foi possivel acessar o Akit.");
            return;
        }

        akit.Callback("acmd_check_database", "1", "main_frame");
        // Repara o banco de dados de bibliotecas (xslib) apos o reparo do modelo.
        akit.Callback("acmd_check_database", "XS_LIB_CORRECT", "main_frame");
    }
}


internal static class Formatters
{
    public static string FormatValue(string value)
    {
        return string.IsNullOrEmpty(value) ? "-" : value;
    }

    public static string FormatValue(object value)
    {
        return value == null ? "-" : value.ToString();
    }

    public static string FormatBool(bool value)
    {
        return value ? "Sim" : "Nao";
    }

    public static string FormatPhaseNumber(ModelObject modelObject)
    {
        if (modelObject == null)
        {
            return "-";
        }

        Phase phase;
        if (modelObject.GetPhase(out phase))
        {
            return phase.PhaseNumber.ToString();
        }

        return "-";
    }

    public static string FormatDate(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            return "-";
        }

        DateTime parsed;
        if (DateTime.TryParse(value, out parsed))
        {
            return parsed.ToString("yyyy-MM-dd");
        }

        return value;
    }
}


internal static class AssemblySelectionHelper
{
    private static readonly StringComparer Comparer = StringComparer.OrdinalIgnoreCase;

    public static void SelectAssemblies(string input)
    {
        if (string.IsNullOrWhiteSpace(input))
        {
            MessageBox.Show("Informe ao menos um nome de conjunto.");
            return;
        }

        var model = ModelHelper.GetConnectedModel();
        if (model == null) return;

        var tokens = input.Split(new[] { ',', '\n', '\r', '\t', ';' }, StringSplitOptions.RemoveEmptyEntries);
        var requestedMapping = new System.Collections.Generic.Dictionary<string, string>(Comparer);
        var requestedOrder = new System.Collections.Generic.List<string>();

        foreach (var token in tokens)
        {
            var trimmed = token.Trim();
            var normalized = NormalizeKey(trimmed);
            if (normalized == null || requestedMapping.ContainsKey(normalized))
            {
                continue;
            }

            requestedMapping[normalized] = trimmed;
            requestedOrder.Add(normalized);
        }

        if (requestedMapping.Count == 0)
        {
            MessageBox.Show("Informe ao menos um nome de conjunto.");
            return;
        }

        var selection = new System.Collections.ArrayList();
        var selectionIds = new System.Collections.Generic.HashSet<long>();
        var foundNames = new System.Collections.Generic.HashSet<string>(Comparer);

        TrySelectAssembliesByFilters(model, requestedOrder, selection, selectionIds, foundNames);

        var missingNormalized = new System.Collections.Generic.HashSet<string>(Comparer);
        foreach (var normalized in requestedMapping.Keys)
        {
            if (!foundNames.Contains(normalized))
            {
                missingNormalized.Add(normalized);
            }
        }

        if (missingNormalized.Count > 0)
        {
            var result = MessageBox.Show("Alguns conjuntos (" + missingNormalized.Count + ") n??o foram achados pelas pesquisas r??pidas. Deseja realizar uma varredura profunda no modelo todo? \n(Isso pode travar por v??rios minutos).", "Pesquisa Profunda", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
            if (result != DialogResult.Yes)
            {
                return;
            }

            var enumerator = model.GetModelObjectSelector().GetAllObjectsWithType(ModelObject.ModelObjectEnum.ASSEMBLY);
            if (enumerator == null)
            {
                MessageBox.Show("Nao foi possivel obter os conjuntos do modelo.");
                return;
            }

            var previousCursor = Cursor.Current;
            Cursor.Current = Cursors.WaitCursor;
            try
            {
                int processed = 0;
                while (enumerator.MoveNext())
                {
                    processed++;
                    if (processed % 200 == 0)
                    {
                        Application.DoEvents();
                    }

                    var assembly = enumerator.Current as Assembly;
                    if (assembly == null)
                    {
                        continue;
                    }

                    foreach (var candidate in GetNormalizedAssemblyKeys(assembly))
                    {
                        if (!missingNormalized.Contains(candidate))
                        {
                            continue;
                        }

                        AddAssemblyToSelection(selection, selectionIds, assembly);
                        foundNames.Add(candidate);
                        missingNormalized.Remove(candidate);
                        break;
                    }

                    if (missingNormalized.Count == 0)
                    {
                        break;
                    }
                }
            }
            finally
            {
                Cursor.Current = previousCursor;
            }
        }

        if (selection.Count == 0)
        {
            MessageBox.Show("Nenhum conjunto encontrado com os nomes informados.");
            return;
        }

        var selector = new ModelUI.ModelObjectSelector();
        selector.Select(selection, false);

        if (foundNames.Count < requestedMapping.Count)
        {
            var missingBuilder = new StringBuilder();
            foreach (var normalized in requestedOrder)
            {
                if (foundNames.Contains(normalized))
                {
                    continue;
                }

                if (missingBuilder.Length > 0)
                {
                    missingBuilder.Append(", ");
                }

                missingBuilder.Append(requestedMapping[normalized]);
            }

            MessageBox.Show("Nao foram encontrados os seguintes conjuntos: " + missingBuilder.ToString());
        }
    }

    private static System.Collections.Generic.IEnumerable<string> GetNormalizedAssemblyKeys(Assembly assembly)
    {
        var seen = new System.Collections.Generic.HashSet<string>(Comparer);

        foreach (var candidate in GetAssemblyCandidateValues(assembly))
        {
            var normalized = NormalizeKey(candidate);
            if (normalized != null && seen.Add(normalized))
            {
                yield return normalized;
            }
        }
    }

    private static System.Collections.Generic.IEnumerable<string> GetAssemblyCandidateValues(Assembly assembly)
    {
        if (!string.IsNullOrWhiteSpace(assembly.Name))
        {
            yield return assembly.Name;
        }

        var number = assembly.AssemblyNumber;
        if (number != null)
        {
            var numberString = number.ToString();
            if (!string.IsNullOrWhiteSpace(numberString))
            {
                yield return numberString;
            }
        }

        var identifier = assembly.Identifier;
        if (identifier != null)
        {
            yield return identifier.ID.ToString();
        }

        foreach (var reportValue in TryGetReportValues(assembly))
        {
            yield return reportValue;
        }
    }

    private static System.Collections.Generic.IEnumerable<string> TryGetReportValues(Assembly assembly)
    {
        foreach (var propertyName in new[] { "POSITION", "ASSEMBLY_POSITION", "ASSEMBLY_POS", "POSITION_NAME", "ASSEMBLY_NUMBER", "POSITION_ID" })
        {
            var reportValue = ModelHelper.GetReportProperty(assembly, propertyName);
            if (!string.IsNullOrWhiteSpace(reportValue) && reportValue != "-")
            {
                yield return reportValue;
            }
        }
    }

    private static string NormalizeKey(string input)
    {
        if (string.IsNullOrWhiteSpace(input))
        {
            return null;
        }

        var trimmed = input.Trim();
        return trimmed.Length == 0 ? null : trimmed;
    }

    private static readonly Func<string, BinaryFilterExpressionCollection>[] AssemblyFilterFactories =
        new Func<string, BinaryFilterExpressionCollection>[]
        {
            value => BuildAssemblyStringFilter(() => new AssemblyFilterExpressions.Name(), value),
            value => BuildAssemblyStringFilter(() => new AssemblyFilterExpressions.PositionNumber(), value)
        };

    private static void TrySelectAssembliesByFilters(Model model, System.Collections.Generic.IEnumerable<string> normalizedKeys, System.Collections.ArrayList selection, System.Collections.Generic.HashSet<long> selectionIds, System.Collections.Generic.HashSet<string> foundNames)
    {
        if (model == null || normalizedKeys == null)
        {
            return;
        }

        var selector = model.GetModelObjectSelector();
        if (selector == null)
        {
            return;
        }

        foreach (var normalized in normalizedKeys)
        {
            if (string.IsNullOrWhiteSpace(normalized) || foundNames.Contains(normalized))
            {
                continue;
            }

            if (TryGatherAssembliesByFilter(selector, normalized, selection, selectionIds))
            {
                foundNames.Add(normalized);
            }
        }
    }

    private static bool TryGatherAssembliesByFilter(ModelObjectSelector selector, string normalized, System.Collections.ArrayList selection, System.Collections.Generic.HashSet<long> selectionIds)
    {
        foreach (var factory in AssemblyFilterFactories)
        {
            var filter = factory(normalized);
            if (filter == null)
            {
                continue;
            }

            var enumerator = selector.GetObjectsByFilter(filter);
            if (enumerator == null)
            {
                continue;
            }

            var found = false;
            while (enumerator.MoveNext())
            {
                var assembly = enumerator.Current as Assembly;
                if (assembly == null)
                {
                    continue;
                }

                AddAssemblyToSelection(selection, selectionIds, assembly);
                found = true;
            }

            if (found)
            {
                return true;
            }
        }

        return false;
    }

    private static void AddAssemblyToSelection(System.Collections.ArrayList selection, System.Collections.Generic.HashSet<long> selectionIds, Assembly assembly)
    {
        if (assembly == null)
        {
            return;
        }

        var identifier = assembly.Identifier;
        if (identifier != null && identifier.ID != 0)
        {
            if (selectionIds.Add(identifier.ID))
            {
                selection.Add(assembly);
            }

            return;
        }

        if (!selection.Contains(assembly))
        {
            selection.Add(assembly);
        }
    }

    private static BinaryFilterExpressionCollection BuildAssemblyStringFilter(Func<StringFilterExpression> propertyFactory, string normalized)
    {
        if (propertyFactory == null || string.IsNullOrWhiteSpace(normalized))
        {
            return null;
        }

        var propertyExpression = propertyFactory();
        if (propertyExpression == null)
        {
            return null;
        }

        var collection = new BinaryFilterExpressionCollection();

        var typeFilter = new BinaryFilterExpression(
            new ObjectFilterExpressions.Type(),
            NumericOperatorType.IS_EQUAL,
            new NumericConstantFilterExpression((int)TeklaStructuresDatabaseTypeEnum.ASSEMBLY));
        collection.Add(new BinaryFilterExpressionItem(typeFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        var stringFilter = new BinaryFilterExpression(
            propertyExpression,
            StringOperatorType.IS_EQUAL,
            new StringConstantFilterExpression(normalized));
        collection.Add(new BinaryFilterExpressionItem(stringFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        return collection;
    }
}


internal static class AssemblyComparator
{
    private const bool IncludeOkDetails = true;
    private const double NumericTolerance = 0.005;

    public static void CompareSelectedAssemblies()
    {
        Model model = ModelHelper.GetConnectedModel();
        if (model == null) return;

        ModelUI.ModelObjectSelector uiSelector = new ModelUI.ModelObjectSelector();
        ModelObjectEnumerator enumSelected = uiSelector.GetSelectedObjects();
        if (enumSelected == null)
        {
            MessageBox.Show("Nenhum objeto selecionado.");
            return;
        }

        ArrayList assemblies = new ArrayList();
        while (enumSelected.MoveNext())
        {
            Assembly ass = enumSelected.Current as Assembly;
            if (ass != null)
            {
                assemblies.Add(ass);
            }
        }

        if (assemblies.Count != 2)
        {
            MessageBox.Show("Selecione exatamente dois conjuntos para comparar.");
            return;
        }

        Assembly ass1 = (Assembly)assemblies[0];
        Assembly ass2 = (Assembly)assemblies[1];

        if (ass1.Identifier.ID == ass2.Identifier.ID)
        {
            MessageBox.Show("Voc?? selecionou a mesma pe??a duas vezes. Selecione duas pe??as diferentes para comparar.");
            return;
        }

        StringBuilder sb = new StringBuilder();
        int totalOk;
        int totalDiff;
        AppendAssemblyComparison(sb, ass1, ass2, model, out totalOk, out totalDiff);

        ReportWindow.ShowReport(sb.ToString(), "Comparacao de Conjuntos");
    }

    private static void AppendAssemblyComparison(StringBuilder sb, Assembly ass1, Assembly ass2, Model model, out int totalOk, out int totalDiff)
    {
        totalOk = 0;
        totalDiff = 0;

        string pos1 = ModelHelper.GetReportProperty(ass1, "ASSEMBLY_POS");
        string pos2 = ModelHelper.GetReportProperty(ass2, "ASSEMBLY_POS");

        sb.AppendLine("=== COMPARADOR DE CONJUNTOS ===");
        sb.AppendLine();
        sb.AppendLine(string.Format("Conjunto 1: {0} (Pos: {1})", Formatters.FormatValue(ass1.Name), pos1));
        sb.AppendLine(string.Format("Conjunto 2: {0} (Pos: {1})", Formatters.FormatValue(ass2.Name), pos2));
        sb.AppendLine(string.Format("Data: {0}", DateTime.Now.ToString("yyyy-MM-dd HH:mm")));
        sb.AppendLine();

        sb.AppendLine("=== SERIE DE NUMERACAO ===");
        int secOk;
        int secDiff;
        bool seriesEqual = AppendNumberingSeriesComparison(sb, ass1, ass2, out secOk, out secDiff);
        totalOk += secOk;
        totalDiff += secDiff;
        sb.AppendLine();

        if (!seriesEqual)
        {
            sb.AppendLine("[X] Comparacao interrompida: series de numeracao diferentes.");
            sb.AppendLine();
            AppendVerdict(sb, totalOk, totalDiff);
            return;
        }

        sb.AppendLine("=== PECA PRINCIPAL ===");
        AppendMainPartComparison(sb, ass1, ass2, out secOk, out secDiff);
        totalOk += secOk;
        totalDiff += secDiff;
        sb.AppendLine();

        sb.AppendLine("=== SECUNDARIAS ===");
        AppendSecondariesComparison(sb, ass1, ass2, model, out secOk, out secDiff);
        totalOk += secOk;
        totalDiff += secDiff;
        sb.AppendLine();

        sb.AppendLine("=== PROPRIEDADES DO CONJUNTO ===");
        AppendAssemblyPropertiesComparison(sb, ass1, ass2, out secOk, out secDiff);
        totalOk += secOk;
        totalDiff += secDiff;
        sb.AppendLine();

        AppendVerdict(sb, totalOk, totalDiff);
    }

    private static void AppendVerdict(StringBuilder sb, int okCount, int diffCount)
    {
        sb.AppendLine("=== RESUMO ===");
        sb.AppendLine(string.Format("Verificacoes: {0} total", okCount + diffCount));
        sb.AppendLine(string.Format("[OK] Iguais: {0}", okCount));
        if (diffCount > 0)
        {
            sb.AppendLine(string.Format("[X] Diferentes: {0}", diffCount));
        }
        sb.AppendLine();

        if (diffCount == 0)
        {
            sb.AppendLine(">>> APROVADO - Conjuntos equivalentes. <<<");
        }
        else
        {
            sb.AppendLine(string.Format(">>> REPROVADO - {0} diferenca(s) encontrada(s). <<<", diffCount));
        }
    }

    private static bool AppendNumberingSeriesComparison(StringBuilder sb, Assembly ass1, Assembly ass2, out int okCount, out int diffCount)
    {
        okCount = 0;
        diffCount = 0;

        string prefix1 = GetAssemblyNumberPrefix(ass1);
        string prefix2 = GetAssemblyNumberPrefix(ass2);
        string start1 = GetAssemblyNumberStart(ass1);
        string start2 = GetAssemblyNumberStart(ass2);

        if (AppendCompareLine(sb, "Prefixo", prefix1, prefix2))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "StartNumber", start1, start2))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        AppendSectionSummary(sb, okCount, diffCount);

        return diffCount == 0;
    }

    private static void AppendMainPartComparison(StringBuilder sb, Assembly ass1, Assembly ass2, out int okCount, out int diffCount)
    {
        okCount = 0;
        diffCount = 0;

        Part main1 = ass1.GetMainPart() as Part;
        Part main2 = ass2.GetMainPart() as Part;

        if (main1 == null || main2 == null)
        {
            sb.AppendLine("[X] Peca principal: nao encontrada em um dos conjuntos.");
            diffCount++;
            return;
        }

        if (AppendCompareLine(sb, "Perfil", ModelHelper.GetReportProperty(main1, "PROFILE"), ModelHelper.GetReportProperty(main2, "PROFILE")))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "Material", ModelHelper.GetReportProperty(main1, "MATERIAL"), ModelHelper.GetReportProperty(main2, "MATERIAL")))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "Acabamento", GetPartFinish(main1), GetPartFinish(main2)))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "Deformacao", ModelHelper.GetReportProperty(main1, "DEFORMATION"), ModelHelper.GetReportProperty(main2, "DEFORMATION")))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "Nome (config)", GetPartName(main1), GetPartName(main2)))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (AppendCompareLine(sb, "Classe (info)", GetPartClass(main1), GetPartClass(main2)))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        string partPrefix1 = GetPartNumberPrefix(main1);
        string partPrefix2 = GetPartNumberPrefix(main2);
        if (AppendCompareLine(sb, "Num. Peca Prefixo", partPrefix1, partPrefix2))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        string partStart1 = GetPartNumberStart(main1);
        string partStart2 = GetPartNumberStart(main2);
        if (AppendCompareLine(sb, "Num. Peca StartNumber", partStart1, partStart2))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        AppendSectionSummary(sb, okCount, diffCount);
    }

    private static void AppendSecondariesComparison(StringBuilder sb, Assembly ass1, Assembly ass2, Model model, out int okCount, out int diffCount)
    {
        okCount = 0;
        diffCount = 0;

        int count1;
        int count2;
        Dictionary<string, int> map1 = BuildSecondarySignatureCounts(ass1, model, out count1);
        Dictionary<string, int> map2 = BuildSecondarySignatureCounts(ass2, model, out count2);

        if (AppendCompareLine(sb, "Quantidade", count1, count2))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        List<string> diffLines = BuildSecondaryDiffLines(map1, map2);
        bool geomOk = diffLines.Count == 0;
        if (AppendStatusLine(sb, "Geometria/posicao relativa", geomOk))
        {
            okCount++;
        }
        else
        {
            diffCount++;
        }

        if (diffLines.Count > 0)
        {
            foreach (string line in diffLines)
            {
                sb.AppendLine(line);
            }
        }

        AppendSectionSummary(sb, okCount, diffCount);
    }

    private static Dictionary<string, int> BuildSecondarySignatureCounts(Assembly ass, Model model, out int count)
    {
        Dictionary<string, int> map = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        count = 0;

        if (ass == null || model == null)
        {
            return map;
        }

        Part main = ass.GetMainPart() as Part;

        WorkPlaneHandler handler = model.GetWorkPlaneHandler();
        TransformationPlane originalPlane = handler.GetCurrentTransformationPlane();

        try
        {
            if (main != null)
            {
                handler.SetCurrentTransformationPlane(new TransformationPlane(main.GetCoordinateSystem()));
            }

            ArrayList secondaries = ass.GetSecondaries();
            foreach (ModelObject obj in secondaries)
            {
                Part part = obj as Part;
                if (part == null)
                {
                    continue;
                }

                count++;
                string signature = BuildSecondarySignature(part);
                int current;
                if (map.TryGetValue(signature, out current))
                {
                    map[signature] = current + 1;
                }
                else
                {
                    map.Add(signature, 1);
                }
            }
        }
        finally
        {
            handler.SetCurrentTransformationPlane(originalPlane);
        }

        return map;
    }

    private static string BuildSecondarySignature(Part part)
    {
        string profile = NormalizeKeyValue(ModelHelper.GetReportProperty(part, "PROFILE"));
        string material = NormalizeKeyValue(ModelHelper.GetReportProperty(part, "MATERIAL"));
        string finish = NormalizeKeyValue(GetPartFinish(part));
        string partClass = NormalizeKeyValue(GetPartClass(part));
        Box box = GetLocalBoundingBox(part);

        return string.Format("Perfil={0};Material={1};Acabamento={2};Classe={3};Box={4}", profile, material, finish, partClass, FormatBox(box));
    }

    private struct Box
    {
        public Tekla.Structures.Geometry3d.Point Min;
        public Tekla.Structures.Geometry3d.Point Max;

        public Box(Tekla.Structures.Geometry3d.Point min, Tekla.Structures.Geometry3d.Point max)
        {
            Min = min;
            Max = max;
        }
    }

    private static Box GetLocalBoundingBox(Part part)
    {
        Solid solid = part.GetSolid();
        if (solid == null || solid.MinimumPoint == null || solid.MaximumPoint == null)
        {
            var zero = new Tekla.Structures.Geometry3d.Point(0, 0, 0);
            return new Box(zero, zero);
        }
        return new Box(solid.MinimumPoint, solid.MaximumPoint);
    }

    private static string FormatBox(Box box)
    {
        return string.Format(
            "Min({0},{1},{2}) Max({3},{4},{5})",
            FormatCoordinate(box.Min.X),
            FormatCoordinate(box.Min.Y),
            FormatCoordinate(box.Min.Z),
            FormatCoordinate(box.Max.X),
            FormatCoordinate(box.Max.Y),
            FormatCoordinate(box.Max.Z));
    }

    private static string FormatCoordinate(double value)
    {
        double rounded = RoundToTolerance(value);
        return string.Format("{0:F3}", rounded);
    }

    private static double RoundToTolerance(double value)
    {
        double tol = GeometryConstants.DISTANCE_EPSILON;
        if (tol <= 0.0)
        {
            tol = 0.001;
        }

        return Math.Round(value / tol) * tol;
    }

    private static List<string> BuildSecondaryDiffLines(Dictionary<string, int> map1, Dictionary<string, int> map2)
    {
        List<string> lines = new List<string>();
        SortedSet<string> keys = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (string key in map1.Keys)
        {
            keys.Add(key);
        }
        foreach (string key in map2.Keys)
        {
            keys.Add(key);
        }

        foreach (string key in keys)
        {
            int count1 = map1.ContainsKey(key) ? map1[key] : 0;
            int count2 = map2.ContainsKey(key) ? map2[key] : 0;

            if (count1 > count2)
            {
                lines.Add(string.Format("[X] Secundaria faltando no conjunto 2 (x{0}):", count1 - count2));
                AppendSignatureReadable(lines, key);
            }
            else if (count2 > count1)
            {
                lines.Add(string.Format("[X] Secundaria extra no conjunto 2 (x{0}):", count2 - count1));
                AppendSignatureReadable(lines, key);
            }
        }

        return lines;
    }

    private static void AppendSignatureReadable(List<string> lines, string signature)
    {
        string[] parts = signature.Split(';');
        foreach (string part in parts)
        {
            int eqIndex = part.IndexOf('=');
            if (eqIndex > 0)
            {
                string label = part.Substring(0, eqIndex).Trim();
                string value = part.Substring(eqIndex + 1).Trim();
                if (string.Equals(label, "Box", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }
                lines.Add(string.Format("      {0}: {1}", label, value));
            }
        }
    }

    private static bool AppendStatusLine(StringBuilder sb, string label, bool ok)
    {
        if (!ok || IncludeOkDetails)
        {
            string mark = ok ? "[OK]" : "[X]";
            string status = ok ? "Iguais" : "Diferentes";
            sb.AppendLine(string.Format("{0} {1}: {2}", mark, label, status));
        }

        return ok;
    }

    private static string GetAssemblyNumberPrefix(Assembly ass)
    {
        if (ass == null || ass.AssemblyNumber == null)
        {
            return "-";
        }

        return Formatters.FormatValue(ass.AssemblyNumber.Prefix);
    }

    private static string GetAssemblyNumberStart(Assembly ass)
    {
        if (ass == null || ass.AssemblyNumber == null)
        {
            return "-";
        }

        return ass.AssemblyNumber.StartNumber.ToString();
    }

    private static string GetPartNumberPrefix(Part part)
    {
        if (part == null || part.PartNumber == null)
        {
            return "-";
        }

        return Formatters.FormatValue(part.PartNumber.Prefix);
    }

    private static string GetPartNumberStart(Part part)
    {
        if (part == null || part.PartNumber == null)
        {
            return "-";
        }

        return part.PartNumber.StartNumber.ToString();
    }

    private static string GetPartFinish(Part part)
    {
        if (part == null)
        {
            return "-";
        }

        return Formatters.FormatValue(part.Finish);
    }

    private static string GetPartName(Part part)
    {
        if (part == null)
        {
            return "-";
        }

        return Formatters.FormatValue(part.Name);
    }

    private static string GetPartClass(Part part)
    {
        if (part == null)
        {
            return "-";
        }

        return part.Class.ToString();
    }

    private static bool AppendCompareLine(StringBuilder sb, string label, string leftValue, string rightValue)
    {
        bool ok = AreEqualNormalized(leftValue, rightValue);
        if (!ok || IncludeOkDetails)
        {
            string mark = ok ? "[OK]" : "[X]";
            sb.AppendLine(string.Format("{0} {1}: {2} | {3}", mark, label, leftValue, rightValue));
        }

        return ok;
    }

    private static bool AppendCompareLine(StringBuilder sb, string label, int leftCount, int rightCount)
    {
        string leftText = FormatQuantity(leftCount);
        string rightText = FormatQuantity(rightCount);
        bool ok = leftCount == rightCount;
        if (!ok || IncludeOkDetails)
        {
            string mark = ok ? "[OK]" : "[X]";
            sb.AppendLine(string.Format("{0} {1}: {2} | {3}", mark, label, leftText, rightText));
        }

        return ok;
    }

    private static bool AppendCompareLineWithTolerance(StringBuilder sb, string label, string leftValue, string rightValue)
    {
        bool exactMatch = AreEqualNormalized(leftValue, rightValue);

        if (exactMatch)
        {
            if (IncludeOkDetails)
            {
                sb.AppendLine(string.Format("[OK] {0}: {1} | {2}", label, leftValue, rightValue));
            }
            return true;
        }

        double leftNum;
        double rightNum;
        bool leftIsNum = double.TryParse(leftValue, out leftNum);
        bool rightIsNum = double.TryParse(rightValue, out rightNum);

        if (leftIsNum && rightIsNum)
        {
            bool withinTolerance = AreEqualWithTolerance(leftNum, rightNum);
            if (withinTolerance)
            {
                sb.AppendLine(string.Format("[~] {0}: {1} | {2} (dentro da tolerancia)", label, leftValue, rightValue));
                return true;
            }
        }

        sb.AppendLine(string.Format("[X] {0}: {1} | {2}", label, leftValue, rightValue));
        return false;
    }

    private static bool AreEqualWithTolerance(double a, double b)
    {
        if (Math.Abs(a - b) < 0.001)
        {
            return true;
        }

        double maxAbs = Math.Max(Math.Abs(a), Math.Abs(b));
        if (maxAbs < 0.001)
        {
            return true;
        }

        double relDiff = Math.Abs(a - b) / maxAbs;
        return relDiff <= NumericTolerance;
    }

    private static void AppendSectionSummary(StringBuilder sb, int okCount, int diffCount)
    {
        if (IncludeOkDetails)
        {
            return;
        }

        if (diffCount == 0 && okCount > 0)
        {
            sb.AppendLine(string.Format("[OK] Todos iguais ({0} linhas ocultas).", okCount));
            return;
        }

        if (okCount > 0)
        {
            sb.AppendLine(string.Format("[OK] Linhas iguais ocultas: {0}", okCount));
        }
    }

    private static string FormatQuantity(int count)
    {
        if (count == 1)
        {
            return "1 peca";
        }

        return string.Format("{0} pecas", count);
    }

    private static void AppendAssemblyPropertiesComparison(StringBuilder sb, Assembly ass1, Assembly ass2, out int okCount, out int diffCount)
    {
        okCount = 0;
        diffCount = 0;

        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "AREA")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "ASSEMBLY_PREFIX")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "WIDTH")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "HEIGHT")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "LENGHT")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "LENGHT_GROSS")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "MATERIAL_TYPE")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "VOLUME")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "WEIGHT")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "WEIGHT_GROSS")) okCount++; else diffCount++;
        if (AppendAssemblyPropertyLine(sb, ass1, ass2, "WEIGHT_NET")) okCount++; else diffCount++;

        AppendSectionSummary(sb, okCount, diffCount);
    }

    private static bool AppendAssemblyPropertyLine(StringBuilder sb, Assembly ass1, Assembly ass2, string propertyName)
    {
        string leftValue = GetAssemblyProperty(ass1, propertyName);
        string rightValue = GetAssemblyProperty(ass2, propertyName);
        return AppendCompareLineWithTolerance(sb, propertyName, leftValue, rightValue);
    }

    private static string GetAssemblyProperty(Assembly ass, string propertyName)
    {
        string value = ModelHelper.GetReportProperty(ass, propertyName);
        if (value == "-")
        {
            if (string.Equals(propertyName, "LENGHT", StringComparison.OrdinalIgnoreCase))
            {
                value = ModelHelper.GetReportProperty(ass, "LENGTH");
            }
            else if (string.Equals(propertyName, "LENGHT_GROSS", StringComparison.OrdinalIgnoreCase))
            {
                value = ModelHelper.GetReportProperty(ass, "LENGTH_GROSS");
            }
        }

        return value;
    }

    private static string NormalizeKeyValue(string value)
    {
        if (string.IsNullOrWhiteSpace(value) || value == "-")
        {
            return "N/A";
        }

        return value.Trim().ToUpperInvariant().Replace(" ", "_");
    }

    private static bool AreEqualNormalized(string left, string right)
    {
        if (left == null)
        {
            left = string.Empty;
        }
        if (right == null)
        {
            right = string.Empty;
        }

        return string.Equals(left.Trim(), right.Trim(), StringComparison.OrdinalIgnoreCase);
    }
}


internal static class NumberingChecker
{
    // Ponto de entrada: extrai prefixos da selecao (todos os niveis de assembly)
    // e verifica as sequencias no modelo para esses prefixos.
    public static string CheckNumberingFromSelection()
    {
        Model model = ModelHelper.GetConnectedModel();
        if (model == null) return null;

        ModelUI.ModelObjectSelector uiSelector = new ModelUI.ModelObjectSelector();
        ModelObjectEnumerator enumSelected = uiSelector.GetSelectedObjects();
        if (enumSelected == null)
        {
            MessageBox.Show("Selecione ao menos uma peca no modelo.", "Verificar Numeracao", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return null;
        }

        // 1. Extrair prefixos de TODOS os niveis de assembly dos objetos selecionados
        //    Sobe a hierarquia: Part -> SubConjunto -> Conjunto principal
        var targetPrefixes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        while (enumSelected.MoveNext())
        {
            ModelObject obj = enumSelected.Current as ModelObject;
            if (obj == null) continue;

            // Resolver o Assembly mais proximo do objeto selecionado
            Assembly startAssembly = obj as Assembly;
            if (startAssembly == null)
            {
                Part part = obj as Part;
                if (part != null)
                {
                    startAssembly = part.GetAssembly() as Assembly;
                }
            }

            if (startAssembly == null) continue;

            // Subir a hierarquia coletando o prefixo de cada nivel
            Assembly cursor = startAssembly;
            int safetyLimit = 10; // evitar loop infinito em hierarquias corrompidas
            while (cursor != null && safetyLimit-- > 0)
            {
                string prefix = ExtractPrefixDirect(cursor);
                if (!string.IsNullOrWhiteSpace(prefix))
                {
                    targetPrefixes.Add(prefix);
                }

                // Subir para o assembly pai
                Assembly parent = null;
                try { parent = cursor.GetAssembly() as Assembly; }
                catch { }
                // Evitar loop se o pai for o proprio objeto
                if (parent != null && parent.Identifier != null && cursor.Identifier != null
                    && parent.Identifier.ID == cursor.Identifier.ID)
                {
                    break;
                }
                cursor = parent;
            }
        }

        if (targetPrefixes.Count == 0)
        {
            MessageBox.Show(
                "Nenhum prefixo identificado nas pecas selecionadas.\nVerifique se as pecas possuem posicao de conjunto definida.",
                "Verificar Numeracao", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return null;
        }

        var prefixList = new List<string>(targetPrefixes);
        prefixList.Sort(StringComparer.OrdinalIgnoreCase);
        string prefixDisplay = string.Join(", ", prefixList.ToArray());

        // 2. Para cada prefixo, consultar o modelo via filtro STARTS_WITH
        //    Funciona para conjuntos principais E subconjuntos (ambos sao Assembly no Tekla)
        var prefixUniqueNumbers = new Dictionary<string, SortedSet<int>>(StringComparer.OrdinalIgnoreCase);
        var prefixTotalCount    = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var emptyPositionIds    = new List<long>();
        int totalAssemblies     = 0;

        ModelObjectSelector modelSelector = model.GetModelObjectSelector();

        var previousCursor = Cursor.Current;
        Cursor.Current = Cursors.WaitCursor;
        try
        {
            foreach (string prefix in prefixList)
            {
                BinaryFilterExpressionCollection filter = BuildPrefixStartsWithFilter(prefix);
                if (filter == null) continue;

                ModelObjectEnumerator enumFiltered = modelSelector.GetObjectsByFilter(filter);
                if (enumFiltered == null) continue;

                while (enumFiltered.MoveNext())
                {
                    Assembly assembly = enumFiltered.Current as Assembly;
                    if (assembly == null) continue;

                    // Ler prefix e numero direto do AssemblyNumber (mais confiavel que ASSEMBLY_POS)
                    string foundPrefix;
                    int number;
                    if (!ExtractPrefixAndNumber(assembly, out foundPrefix, out number)) continue;

                    // STARTS_WITH pode retornar "PPP1" ao buscar "PP" - checar prefixo exato
                    if (!string.Equals(foundPrefix, prefix, StringComparison.OrdinalIgnoreCase)) continue;

                    totalAssemblies++;

                    int currentCount;
                    prefixTotalCount.TryGetValue(prefix, out currentCount);
                    prefixTotalCount[prefix] = currentCount + 1;

                    SortedSet<int> uniqueNums;
                    if (!prefixUniqueNumbers.TryGetValue(prefix, out uniqueNums))
                    {
                        uniqueNums = new SortedSet<int>();
                        prefixUniqueNumbers[prefix] = uniqueNums;
                    }
                    uniqueNums.Add(number);
                }
            }

            // Assemblies sem posicao (busca separada no modelo inteiro)
            BinaryFilterExpressionCollection emptyFilter = BuildEmptyPositionFilter();
            if (emptyFilter != null)
            {
                ModelObjectEnumerator enumEmpty = modelSelector.GetObjectsByFilter(emptyFilter);
                if (enumEmpty != null)
                {
                    while (enumEmpty.MoveNext())
                    {
                        Assembly assembly = enumEmpty.Current as Assembly;
                        if (assembly == null) continue;
                        long id = assembly.Identifier != null ? assembly.Identifier.ID : 0;
                        emptyPositionIds.Add(id);
                    }
                }
            }
        }
        finally
        {
            Cursor.Current = previousCursor;
        }

        if (totalAssemblies == 0 && emptyPositionIds.Count == 0)
        {
            MessageBox.Show(string.Format("Nenhum conjunto encontrado para os prefixos: {0}", prefixDisplay));
            return null;
        }

        return FormatReport(prefixDisplay, totalAssemblies, emptyPositionIds, prefixUniqueNumbers, prefixTotalCount, prefixList);
    }

    // Le o prefixo diretamente de AssemblyNumber.Prefix (sem depender de report property)
    // Mais confiavel para subconjuntos que podem nao ter ASSEMBLY_POS calculado
    private static string ExtractPrefixDirect(Assembly assembly)
    {
        if (assembly == null) return null;
        try
        {
            var num = assembly.AssemblyNumber;
            if (num == null) return null;
            string prefix = num.Prefix;
            return string.IsNullOrWhiteSpace(prefix) ? null : prefix.Trim();
        }
        catch { return null; }
    }

    // Le prefixo e numero diretamente de AssemblyNumber
    private static bool ExtractPrefixAndNumber(Assembly assembly, out string prefix, out int number)
    {
        prefix = null;
        number = 0;
        if (assembly == null) return false;
        try
        {
            var num = assembly.AssemblyNumber;
            if (num == null) return false;
            prefix = num.Prefix;
            if (string.IsNullOrWhiteSpace(prefix)) return false;
            prefix = prefix.Trim();
            number = num.StartNumber;
            return true;
        }
        catch { return false; }
    }

    // Filtro: ASSEMBLY cujo PositionNumber comeca com o prefixo
    // Funciona tanto para conjuntos principais quanto subconjuntos
    private static BinaryFilterExpressionCollection BuildPrefixStartsWithFilter(string prefix)
    {
        if (string.IsNullOrWhiteSpace(prefix)) return null;

        var collection = new BinaryFilterExpressionCollection();

        var typeFilter = new BinaryFilterExpression(
            new ObjectFilterExpressions.Type(),
            NumericOperatorType.IS_EQUAL,
            new NumericConstantFilterExpression((int)TeklaStructuresDatabaseTypeEnum.ASSEMBLY));
        collection.Add(new BinaryFilterExpressionItem(typeFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        var posFilter = new BinaryFilterExpression(
            new AssemblyFilterExpressions.PositionNumber(),
            StringOperatorType.STARTS_WITH,
            new StringConstantFilterExpression(prefix));
        collection.Add(new BinaryFilterExpressionItem(posFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        return collection;
    }

    // Filtro: ASSEMBLY com posicao vazia
    private static BinaryFilterExpressionCollection BuildEmptyPositionFilter()
    {
        var collection = new BinaryFilterExpressionCollection();

        var typeFilter = new BinaryFilterExpression(
            new ObjectFilterExpressions.Type(),
            NumericOperatorType.IS_EQUAL,
            new NumericConstantFilterExpression((int)TeklaStructuresDatabaseTypeEnum.ASSEMBLY));
        collection.Add(new BinaryFilterExpressionItem(typeFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        var emptyFilter = new BinaryFilterExpression(
            new AssemblyFilterExpressions.PositionNumber(),
            StringOperatorType.IS_EQUAL,
            new StringConstantFilterExpression(string.Empty));
        collection.Add(new BinaryFilterExpressionItem(emptyFilter, BinaryFilterOperatorType.BOOLEAN_AND));

        return collection;
    }

    private static string FormatReport(
        string prefixDisplay,
        int totalAssemblies,
        List<long> emptyIds,
        Dictionary<string, SortedSet<int>> prefixUniqueNumbers,
        Dictionary<string, int> prefixTotalCount,
        List<string> sortedPrefixes)
    {
        StringBuilder sb = new StringBuilder();
        int gapCount   = 0;
        int errorCount = 0;

        sb.AppendLine("=== VERIFICADOR DE NUMERACAO ===");
        sb.AppendLine(string.Format("Data: {0}", DateTime.Now.ToString("yyyy-MM-dd HH:mm")));
        sb.AppendLine(string.Format("Prefixos verificados: {0}", prefixDisplay));
        sb.AppendLine(string.Format("Total de conjuntos encontrados: {0}", totalAssemblies));
        sb.AppendLine();

        // 1. Sem posicao
        sb.AppendLine("--- Conjuntos sem posicao ---");
        if (emptyIds.Count == 0)
        {
            sb.AppendLine("[OK] Nenhum conjunto sem posicao encontrado.");
        }
        else
        {
            sb.AppendLine(string.Format("[X] {0} conjunto(s) sem posicao:", emptyIds.Count));
            int showMax = Math.Min(emptyIds.Count, 15);
            for (int i = 0; i < showMax; i++)
                sb.AppendLine(string.Format("    - ID: {0}", emptyIds[i]));
            if (emptyIds.Count > showMax)
                sb.AppendLine(string.Format("    ... e mais {0} conjuntos.", emptyIds.Count - showMax));
            errorCount++;
        }
        sb.AppendLine();

        // 2. Gaps por prefixo
        sb.AppendLine("--- Gaps na sequencia de numeracao ---");

        foreach (string prefix in sortedPrefixes)
        {
            SortedSet<int> uniqueNums;
            if (!prefixUniqueNumbers.TryGetValue(prefix, out uniqueNums) || uniqueNums.Count == 0)
            {
                sb.AppendLine(string.Format("[~] Serie \"{0}\": nenhum conjunto encontrado.", prefix));
                continue;
            }

            if (uniqueNums.Count == 1)
            {
                int only = 0;
                foreach (int n in uniqueNums) { only = n; }
                sb.AppendLine(string.Format("[OK] Serie \"{0}\": 1 posicao ({0}{1}). Sem gaps.", prefix, only));
                continue;
            }

            int min = 0, max = 0;
            bool isFirst = true;
            foreach (int n in uniqueNums)
            {
                if (isFirst) { min = n; isFirst = false; }
                max = n;
            }

            var gaps = new List<int>();
            for (int n = min + 1; n < max; n++)
            {
                if (!uniqueNums.Contains(n))
                {
                    gaps.Add(n);
                    if (gaps.Count >= 50) break;
                }
            }

            if (gaps.Count > 0)
            {
                gapCount += gaps.Count;
                sb.AppendLine(string.Format("[X] Serie \"{0}\": {1} posicao(oes) faltando (de {0}{2} a {0}{3}):",
                    prefix, gaps.Count, min, max));
                sb.AppendLine(string.Format("    Faltam: {0}", JoinInts(gaps, 20)));
            }
            else
            {
                sb.AppendLine(string.Format("[OK] Serie \"{0}\": sem gaps ({0}{1} a {0}{2}).", prefix, min, max));
            }
        }
        sb.AppendLine();

        // 3. Resumo das series
        sb.AppendLine("--- Resumo das series ---");
        foreach (string prefix in sortedPrefixes)
        {
            SortedSet<int> uniqueNums;
            int total;
            prefixUniqueNumbers.TryGetValue(prefix, out uniqueNums);
            prefixTotalCount.TryGetValue(prefix, out total);
            if (uniqueNums == null || uniqueNums.Count == 0) continue;

            int min = 0, max = 0;
            bool isFirst = true;
            foreach (int n in uniqueNums)
            {
                if (isFirst) { min = n; isFirst = false; }
                max = n;
            }

            sb.AppendLine(string.Format("[OK] {0}: {1} posicoes unicas | {2} conjuntos no total | intervalo {0}{3} a {0}{4}",
                prefix, uniqueNums.Count, total, min, max));
        }
        sb.AppendLine();

        // 4. Veredicto
        sb.AppendLine("=== RESUMO ===");
        if (errorCount == 0 && gapCount == 0)
        {
            sb.AppendLine("[OK] Nenhum problema encontrado.");
            sb.AppendLine();
            sb.AppendLine(">>> APROVADO - Numeracao consistente. <<<");
        }
        else
        {
            if (errorCount > 0)
                sb.AppendLine(string.Format("[X] Conjuntos sem posicao: {0}", emptyIds.Count));
            if (gapCount > 0)
                sb.AppendLine(string.Format("[X] Posicoes faltando na sequencia: {0}", gapCount));
            sb.AppendLine();
            sb.AppendLine(string.Format(">>> REPROVADO - {0} problema(s) encontrado(s). <<<",
                errorCount + (gapCount > 0 ? 1 : 0)));
        }

        return sb.ToString();
    }

    private static string JoinInts(List<int> values, int max)
    {
        StringBuilder sb = new StringBuilder();
        int count = Math.Min(values.Count, max);
        for (int i = 0; i < count; i++)
        {
            if (i > 0) sb.Append(", ");
            sb.Append(values[i].ToString());
        }
        if (values.Count > max)
            sb.Append(string.Format(" ... (+{0} outros)", values.Count - max));
        return sb.ToString();
    }
}


internal static class DrawingModelLinker
{
    // Selecionar no modelo a partir da marca digitada do desenho
    public static void SelectModelPartFromDrawingMark(string mark)
    {
        if (string.IsNullOrWhiteSpace(mark))
        {
            MessageBox.Show("Por favor, digite o nome/marca do desenho.", "Caixa Vazia", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        mark = mark.Trim();
        string cleanInput = NormalizeMark(mark);
        if (cleanInput.Length == 0)
        {
            MessageBox.Show("A marca informada nao contem caracteres validos.", "Entrada invalida", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        Model model = ModelHelper.GetConnectedModel();
        if (model == null)
        {
            return;
        }

        Tekla.Structures.Drawing.DrawingHandler drawingHandler = new Tekla.Structures.Drawing.DrawingHandler();
        Tekla.Structures.Drawing.DrawingEnumerator drawings = drawingHandler.GetDrawings();
        if (drawings == null)
        {
            MessageBox.Show("Nao foi possivel acessar a lista de desenhos.");
            return;
        }

        Tekla.Structures.Drawing.Drawing bestDrawing = null;
        Identifier bestIdentifier = null;
        int bestScore = 0;

        while (drawings.MoveNext())
        {
            Tekla.Structures.Drawing.Drawing drawing = drawings.Current as Tekla.Structures.Drawing.Drawing;
            if (drawing == null)
            {
                continue;
            }

            Identifier modelIdentifier = GetDrawingModelIdentifier(drawing);
            if (modelIdentifier == null)
            {
                continue;
            }

            int score = GetDrawingMatchScore(cleanInput, drawing.Mark, drawing.Name);
            if (score <= bestScore)
            {
                continue;
            }

            bestScore = score;
            bestDrawing = drawing;
            bestIdentifier = modelIdentifier;
        }

        if (bestIdentifier == null)
        {
            MessageBox.Show(
                string.Format("Desenho '{0}' nao encontrado na lista de desenhos.\n\nVerifique o 'Mark' ou 'Name' no Document Manager.", mark),
                "Nao encontrado",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information);
            return;
        }

        ModelObject modelObj = model.SelectModelObject(bestIdentifier);
        if (modelObj == null)
        {
            MessageBox.Show(
                string.Format("O desenho '{0}' foi localizado, mas a peca base nao foi encontrada no modelo.", mark),
                "Peca nao encontrada",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information);
            return;
        }

        var selector = new ModelUI.ModelObjectSelector();
        selector.Select(new ArrayList() { modelObj }, false);

        Tekla.Structures.Model.Operations.Operation.DisplayPrompt(
            string.Format("Desenho [{0}] -> Peca do modelo base selecionada!", Formatters.FormatValue(bestDrawing == null ? null : bestDrawing.Mark)));

        try
        {
            Tekla.Structures.Model.Operations.Operation.RunMacro("ZoomToSelected");
        }
        catch
        {
            // Nao bloquear o fluxo se a macro de zoom nao existir.
        }
    }

    private static Identifier GetDrawingModelIdentifier(Tekla.Structures.Drawing.Drawing drawing)
    {
        if (drawing == null)
        {
            return null;
        }

        Tekla.Structures.Drawing.AssemblyDrawing assemblyDrawing = drawing as Tekla.Structures.Drawing.AssemblyDrawing;
        if (assemblyDrawing != null)
        {
            return assemblyDrawing.AssemblyIdentifier;
        }

        Tekla.Structures.Drawing.SinglePartDrawing singlePartDrawing = drawing as Tekla.Structures.Drawing.SinglePartDrawing;
        if (singlePartDrawing != null)
        {
            return singlePartDrawing.PartIdentifier;
        }

        Tekla.Structures.Drawing.CastUnitDrawing castUnitDrawing = drawing as Tekla.Structures.Drawing.CastUnitDrawing;
        if (castUnitDrawing != null)
        {
            return castUnitDrawing.CastUnitIdentifier;
        }

        return null;
    }

    private static int GetDrawingMatchScore(string normalizedInput, string drawingMark, string drawingName)
    {
        if (string.IsNullOrEmpty(normalizedInput))
        {
            return 0;
        }

        int best = 0;

        // Match exato da marca principal do desenho (ex.: PM.13 em "[PM.13 - 1]").
        string primaryMark = ExtractPrimaryMark(drawingMark);
        if (IsExactNormalizedMatch(normalizedInput, primaryMark))
        {
            best = 220;
        }

        // Match exato da marca completa (com sufixos, quando informado).
        if (IsExactNormalizedMatch(normalizedInput, drawingMark) && best < 180)
        {
            best = 180;
        }

        // Match exato do nome do desenho como fallback.
        if (IsExactNormalizedMatch(normalizedInput, drawingName) && best < 140)
        {
            best = 140;
        }

        return best;
    }

    private static bool IsExactNormalizedMatch(string normalizedInput, string text)
    {
        if (string.IsNullOrEmpty(normalizedInput) || string.IsNullOrWhiteSpace(text))
        {
            return false;
        }

        string normalizedText = NormalizeMark(text);
        if (normalizedText.Length == 0)
        {
            return false;
        }

        return string.Equals(normalizedInput, normalizedText, StringComparison.Ordinal);
    }

    private static string ExtractPrimaryMark(string mark)
    {
        if (string.IsNullOrWhiteSpace(mark))
        {
            return string.Empty;
        }

        string clean = mark.Trim();
        if (clean.StartsWith("[", StringComparison.Ordinal) && clean.EndsWith("]", StringComparison.Ordinal) && clean.Length > 1)
        {
            clean = clean.Substring(1, clean.Length - 2).Trim();
        }

        int separatorIndex = clean.IndexOf(" - ", StringComparison.Ordinal);
        if (separatorIndex > 0)
        {
            return clean.Substring(0, separatorIndex).Trim();
        }

        return clean;
    }

    private static string NormalizeMark(string mark)
    {
        if (string.IsNullOrWhiteSpace(mark))
        {
            return string.Empty;
        }

        var sb = new StringBuilder(mark.Length);
        for (int i = 0; i < mark.Length; i++)
        {
            char c = mark[i];
            if (char.IsLetterOrDigit(c))
            {
                sb.Append(char.ToUpperInvariant(c));
            }
        }

        return sb.ToString();
    }
}


// ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
// 95_IsometricViewCreator.cs ??? Cria desenho com 4 vistas 3D
// Cria um GADrawing com 4 perspectivas isometricas da peca/
// assembly selecionado no modelo.
//
// LIMITACOES CONHECIDAS DA TEKLA OPEN API:
// - A API de desenhos (Tekla.Structures.Drawing) nao oferece
//   um metodo direto "Create3dView" ou "CreateIsometricView".
// - A vista 3D e criada via construtor View() com CoordinateSystem
//   rotacionado para simular a projecao isometrica.
// - O resultado e uma projecao ortografica orientada ??? nao
//   uma perspectiva conica real. Para engenharia, isso e o
//   padrao e o comportamento esperado.
// - O layout 2x2 e posicionado manualmente via View.Origin.
// ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
internal static class IsometricViewCreator
{
    // Nomes romanos das 4 vistas
    private static readonly string[] ROMAN = new string[] { "I", "II", "III", "IV" };

    // Angulos de rotacao em Z para cada vista (graus)
    private static readonly double[] Z_ANGLES = new double[] { 45.0, 135.0, 225.0, 315.0 };

    // Angulo de elevacao em X (graus) ??? igual para todas
    private const double X_ANGLE = 25.0;

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Ponto de entrada publico
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    public static void CreateIsometricDrawing()
    {
        // 1. Obter a peca selecionada
        Part selectedPart = GetSelectedPart();
        if (selectedPart == null) return;

        // 2. Obter o assembly pai (ou a propria peca se nao tiver)
        Assembly assembly = selectedPart.GetAssembly();
        if (assembly == null)
        {
            MessageBox.Show(
                "Nao foi possivel obter o conjunto (Assembly) da peca selecionada.",
                "Erro", MessageBoxButtons.OK, MessageBoxIcon.Error);
            return;
        }

        // Garantir que o assembly esta completamente populado no banco
        if (!assembly.Select())
        {
            MessageBox.Show(
                "Nao foi possivel carregar os dados do assembly.\nVerifique se a peca pertence a um conjunto valido.",
                "Erro", MessageBoxButtons.OK, MessageBoxIcon.Error);
            return;
        }

        // 3. Obter nome amigavel
        string displayName = GetPartDisplayName(selectedPart, assembly);

        // 4. Calcular bounding box do assembly
        AABB boundingBox = GetAssemblyBoundingBox(assembly);
        if (boundingBox == null)
        {
            MessageBox.Show(
                "Nao foi possivel calcular o volume da peca selecionada.",
                "Erro", MessageBoxButtons.OK, MessageBoxIcon.Error);
            return;
        }

        // 5. Criar o desenho (tenta AssemblyDrawing, fallback para SinglePartDrawing)
        Tekla.Structures.Drawing.Drawing drawing = CreateDrawing(assembly, selectedPart, displayName);
        if (drawing == null) return;

        // 6. Criar as 4 vistas isometricas
        bool viewsCreated = CreatePerspectiveViews(drawing, boundingBox, displayName);
        if (!viewsCreated)
        {
            MessageBox.Show(
                string.Format("O desenho '{0}' foi criado, mas houve falha ao inserir as vistas.\nAbra o desenho manualmente no Document Manager.", displayName),
                "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        // 6b. Esconder todos os objetos que NAO pertencem ao assembly selecionado
        HideNonAssemblyObjects(drawing, assembly, selectedPart);

        // 7. Abrir o desenho
        OpenDrawing(drawing, displayName);
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Obter exatamente 1 Part da selecao
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static Part GetSelectedPart()
    {
        Model model = ModelHelper.GetConnectedModel();
        if (model == null) return null;

        ModelUI.ModelObjectSelector selector = new ModelUI.ModelObjectSelector();
        ModelObjectEnumerator selected = selector.GetSelectedObjects();
        if (selected == null || selected.GetSize() == 0)
        {
            MessageBox.Show(
                "Selecione uma peca antes de executar a macro.",
                "Nenhuma selecao", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return null;
        }

        if (selected.GetSize() > 1)
        {
            MessageBox.Show(
                "Selecione apenas uma peca por vez.",
                "Multiplas pecas", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return null;
        }

        selected.MoveNext();
        ModelObject obj = selected.Current;

        // Se selecionou um Assembly, pegar a peca principal
        Assembly ass = obj as Assembly;
        if (ass != null)
        {
            Part mainPart = ass.GetMainPart() as Part;
            if (mainPart != null) return mainPart;
        }

        Part part = obj as Part;
        if (part != null) return part;

        MessageBox.Show(
            "O objeto selecionado nao e uma peca valida (Part).\nSelecione uma peca de concreto ou aco no modelo.",
            "Tipo invalido", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        return null;
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Nome amigavel para a peca
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static string GetPartDisplayName(Part part, Assembly assembly)
    {
        // Tentar ASSEMBLY_POS primeiro (ex: "PP-1")
        string assemblyPos = ModelHelper.GetReportProperty(assembly, "ASSEMBLY_POS");
        if (assemblyPos != null && assemblyPos != "-" && assemblyPos.Trim().Length > 0)
        {
            return SanitizeName(assemblyPos.Trim());
        }

        // Tentar PART_POS
        string partPos = ModelHelper.GetReportProperty(part, "PART_POS");
        if (partPos != null && partPos != "-" && partPos.Trim().Length > 0)
        {
            return SanitizeName(partPos.Trim());
        }

        // Nome da peca
        if (!string.IsNullOrEmpty(part.Name))
        {
            return SanitizeName(part.Name.Trim());
        }

        // Fallback: ID
        if (part.Identifier != null)
        {
            return string.Format("ID_{0}", part.Identifier.ID);
        }

        return "Peca";
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Sanitizar nome para uso em titulos
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static string SanitizeName(string name)
    {
        if (string.IsNullOrEmpty(name)) return "Peca";

        var sb = new StringBuilder(name.Length);
        for (int i = 0; i < name.Length; i++)
        {
            char c = name[i];
            if (char.IsLetterOrDigit(c) || c == '-' || c == '_' || c == '.' || c == ' ')
            {
                sb.Append(c);
            }
        }

        string result = sb.ToString().Trim();
        return result.Length > 0 ? result : "Peca";
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Bounding box do assembly (todas as pecas)
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static AABB GetAssemblyBoundingBox(Assembly assembly)
    {
        try
        {
            ArrayList parts = assembly.GetSubAssemblies();
            Part mainPart = assembly.GetMainPart() as Part;

            double minX = double.MaxValue, minY = double.MaxValue, minZ = double.MaxValue;
            double maxX = double.MinValue, maxY = double.MinValue, maxZ = double.MinValue;
            bool hasData = false;

            // Processar a peca principal
            if (mainPart != null)
            {
                Solid solid = mainPart.GetSolid();
                if (solid != null)
                {
                    ExpandBounds(solid.MinimumPoint, solid.MaximumPoint,
                        ref minX, ref minY, ref minZ, ref maxX, ref maxY, ref maxZ);
                    hasData = true;
                }
            }

            // Processar secundarias do assembly
            ArrayList secondaries = assembly.GetSecondaries();
            if (secondaries != null)
            {
                for (int i = 0; i < secondaries.Count; i++)
                {
                    Part secPart = secondaries[i] as Part;
                    if (secPart == null) continue;

                    Solid solid = secPart.GetSolid();
                    if (solid == null) continue;

                    ExpandBounds(solid.MinimumPoint, solid.MaximumPoint,
                        ref minX, ref minY, ref minZ, ref maxX, ref maxY, ref maxZ);
                    hasData = true;
                }
            }

            if (!hasData) return null;

            // Adicionar margem de 10% em cada direcao
            double marginX = (maxX - minX) * 0.10;
            double marginY = (maxY - minY) * 0.10;
            double marginZ = (maxZ - minZ) * 0.10;
            double minMargin = 100.0; // mm minimo
            if (marginX < minMargin) marginX = minMargin;
            if (marginY < minMargin) marginY = minMargin;
            if (marginZ < minMargin) marginZ = minMargin;

            return new AABB(
                new Tekla.Structures.Geometry3d.Point(minX - marginX, minY - marginY, minZ - marginZ),
                new Tekla.Structures.Geometry3d.Point(maxX + marginX, maxY + marginY, maxZ + marginZ));
        }
        catch
        {
            return null;
        }
    }

    private static void ExpandBounds(Tekla.Structures.Geometry3d.Point min, Tekla.Structures.Geometry3d.Point max,
        ref double minX, ref double minY, ref double minZ,
        ref double maxX, ref double maxY, ref double maxZ)
    {
        if (min == null || max == null) return;
        if (min.X < minX) minX = min.X;
        if (min.Y < minY) minY = min.Y;
        if (min.Z < minZ) minZ = min.Z;
        if (max.X > maxX) maxX = max.X;
        if (max.Y > maxY) maxY = max.Y;
        if (max.Z > maxZ) maxZ = max.Z;
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Criar desenho ??? tenta os 3 tipos de desenho na ordem:
    //   1. CastUnitDrawing (concreto pre-fabricado)
    //   2. AssemblyDrawing (aco / assemblies reais)
    //   3. SinglePartDrawing (pecas simples)
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static Tekla.Structures.Drawing.Drawing CreateDrawing(
        Assembly assembly, Part selectedPart, string displayName)
    {
        Tekla.Structures.Drawing.DrawingHandler drawingHandler =
            new Tekla.Structures.Drawing.DrawingHandler();

        // Fechar desenho ativo se houver
        try { drawingHandler.CloseActiveDrawing(); }
        catch { /* Ignorar se nao ha desenho ativo */ }

        // Garantir que o modelo esta sincronizado
        Model commitModel = new Model();
        commitModel.CommitChanges();

        // Garantir que a peca esta completamente carregada
        if (selectedPart != null) selectedPart.Select();

        string lastError = "";

        // Tentativa 1: CastUnitDrawing com assembly ID (para concreto pre-fabricado)
        // O CastUnit E o Assembly retornado por GetAssembly() em pecas de concreto
        try
        {
            if (assembly != null && assembly.Identifier != null && assembly.Identifier.ID > 0)
            {
                Tekla.Structures.Drawing.CastUnitDrawing cuDrawing =
                    new Tekla.Structures.Drawing.CastUnitDrawing(assembly.Identifier);
                cuDrawing.Name = string.Format("3D_{0}", displayName);

                if (cuDrawing.Insert())
                {
                    RemoveDefaultViews(cuDrawing);
                    return cuDrawing;
                }
                lastError = "CastUnitDrawing(assembly).Insert() retornou false";
            }
        }
        catch (Exception ex1)
        {
            lastError = string.Format("CastUnit(asm): {0}", ex1.Message);
        }

        // Tentativa 1b: CastUnitDrawing com part ID (variante)
        try
        {
            if (selectedPart != null && selectedPart.Identifier != null && selectedPart.Identifier.ID > 0)
            {
                Tekla.Structures.Drawing.CastUnitDrawing cuDrawing2 =
                    new Tekla.Structures.Drawing.CastUnitDrawing(selectedPart.Identifier);
                cuDrawing2.Name = string.Format("3D_{0}", displayName);

                if (cuDrawing2.Insert())
                {
                    RemoveDefaultViews(cuDrawing2);
                    return cuDrawing2;
                }
                lastError = "CastUnitDrawing(part).Insert() retornou false";
            }
        }
        catch (Exception ex1b)
        {
            lastError = string.Format("CastUnit(part): {0}", ex1b.Message);
        }

        // Tentativa 2: AssemblyDrawing (para pecas de aco)
        try
        {
            if (assembly != null && assembly.Identifier != null && assembly.Identifier.ID > 0)
            {
                Tekla.Structures.Drawing.AssemblyDrawing asmDrawing =
                    new Tekla.Structures.Drawing.AssemblyDrawing(assembly.Identifier);
                asmDrawing.Name = string.Format("3D_{0}", displayName);

                if (asmDrawing.Insert())
                {
                    RemoveDefaultViews(asmDrawing);
                    return asmDrawing;
                }
                lastError = "AssemblyDrawing.Insert() retornou false";
            }
        }
        catch (Exception ex2)
        {
            lastError = string.Format("Assembly: {0}", ex2.Message);
        }

        // Tentativa 3: SinglePartDrawing (ultimo recurso)
        try
        {
            if (selectedPart != null && selectedPart.Identifier != null && selectedPart.Identifier.ID > 0)
            {
                Tekla.Structures.Drawing.SinglePartDrawing spDrawing =
                    new Tekla.Structures.Drawing.SinglePartDrawing(selectedPart.Identifier);
                spDrawing.Name = string.Format("3D_{0}", displayName);

                if (spDrawing.Insert())
                {
                    RemoveDefaultViews(spDrawing);
                    return spDrawing;
                }
                lastError = "SinglePartDrawing.Insert() retornou false";
            }
        }
        catch (Exception ex3)
        {
            lastError = string.Format("SinglePart: {0}", ex3.Message);
        }

        MessageBox.Show(
            string.Format("Nao foi possivel criar nenhum tipo de desenho para esta peca.\n\nUltimo erro: {0}\n\nTipo da peca: {1}\nID peca: {2}\nID assembly: {3}",
                lastError,
                selectedPart != null ? selectedPart.GetType().Name : "null",
                selectedPart != null && selectedPart.Identifier != null ? selectedPart.Identifier.ID.ToString() : "?",
                assembly != null && assembly.Identifier != null ? assembly.Identifier.ID.ToString() : "?"),
            "Erro", MessageBoxButtons.OK, MessageBoxIcon.Error);
        return null;
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Esconder objetos que NAO pertencem ao assembly alvo
    // Percorre cada vista do desenho e esconde pecas
    // cujo ID de modelo nao faz parte do assembly selecionado.
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static void HideNonAssemblyObjects(
        Tekla.Structures.Drawing.Drawing drawing,
        Assembly assembly,
        Part selectedPart)
    {
        try
        {
            // 1. Coletar todos os IDs de pecas do assembly alvo
            System.Collections.Generic.HashSet<int> allowedIds = new System.Collections.Generic.HashSet<int>();

            // Peca principal
            if (selectedPart != null && selectedPart.Identifier != null)
            {
                allowedIds.Add(selectedPart.Identifier.ID);
            }

            // Peca principal do assembly (pode ser diferente se selecao veio por Assembly)
            if (assembly != null)
            {
                Part mainPart = assembly.GetMainPart() as Part;
                if (mainPart != null && mainPart.Identifier != null)
                {
                    allowedIds.Add(mainPart.Identifier.ID);
                }

                // Pecas secundarias
                ArrayList secondaries = assembly.GetSecondaries();
                if (secondaries != null)
                {
                    for (int i = 0; i < secondaries.Count; i++)
                    {
                        Part secPart = secondaries[i] as Part;
                        if (secPart != null && secPart.Identifier != null)
                        {
                            allowedIds.Add(secPart.Identifier.ID);
                        }
                    }
                }

                // Sub-assemblies (recursivo ??? nao profundo, apenas 1 nivel)
                ArrayList subAssemblies = assembly.GetSubAssemblies();
                if (subAssemblies != null)
                {
                    for (int i = 0; i < subAssemblies.Count; i++)
                    {
                        Assembly subAsm = subAssemblies[i] as Assembly;
                        if (subAsm == null) continue;

                        Part subMain = subAsm.GetMainPart() as Part;
                        if (subMain != null && subMain.Identifier != null)
                        {
                            allowedIds.Add(subMain.Identifier.ID);
                        }

                        ArrayList subSecs = subAsm.GetSecondaries();
                        if (subSecs != null)
                        {
                            for (int j = 0; j < subSecs.Count; j++)
                            {
                                Part sp = subSecs[j] as Part;
                                if (sp != null && sp.Identifier != null)
                                {
                                    allowedIds.Add(sp.Identifier.ID);
                                }
                            }
                        }
                    }
                }

                // O proprio assembly tambem
                if (assembly.Identifier != null)
                {
                    allowedIds.Add(assembly.Identifier.ID);
                }
            }

            if (allowedIds.Count == 0) return;

            // 2. Percorrer cada vista e esconder objetos nao pertencentes
            Tekla.Structures.Drawing.ContainerView sheet = drawing.GetSheet();
            if (sheet == null) return;

            Tekla.Structures.Drawing.DrawingObjectEnumerator sheetObjects = sheet.GetObjects();
            if (sheetObjects == null) return;

            while (sheetObjects.MoveNext())
            {
                Tekla.Structures.Drawing.View view =
                    sheetObjects.Current as Tekla.Structures.Drawing.View;
                if (view == null) continue;

                // Obter todos os objetos desta vista
                Tekla.Structures.Drawing.DrawingObjectEnumerator viewObjects =
                    view.GetObjects();
                if (viewObjects == null) continue;

                while (viewObjects.MoveNext())
                {
                    Tekla.Structures.Drawing.DrawingObject drawObj = viewObjects.Current;
                    if (drawObj == null) continue;

                    // Verificar se e uma Part de desenho
                    Tekla.Structures.Drawing.Part drawPart =
                        drawObj as Tekla.Structures.Drawing.Part;
                    if (drawPart == null) continue;

                    // Obter o Identifier do modelo vinculado
                    try
                    {
                        Tekla.Structures.Identifier modelId = drawPart.ModelIdentifier;
                        if (modelId == null) continue;

                        // Se NAO pertence ao assembly, remover da vista
                        if (!allowedIds.Contains(modelId.ID))
                        {
                            drawPart.Delete();
                        }
                    }
                    catch
                    {
                        // Ignorar objetos sem ModelIdentifier
                    }
                }
            }

            // Salvar as alteracoes
            drawing.CommitChanges();
        }
        catch
        {
            // Nao bloquear se a filtragem falhar ??? o desenho fica "sujo"
            // mas e melhor que nao ter desenho nenhum
        }
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Remover vistas auto-geradas do Assembly Drawing
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static void RemoveDefaultViews(Tekla.Structures.Drawing.Drawing drawing)
    {
        try
        {
            Tekla.Structures.Drawing.ContainerView sheet = drawing.GetSheet();
            if (sheet == null) return;

            Tekla.Structures.Drawing.DrawingObjectEnumerator objects = sheet.GetObjects();
            if (objects == null) return;

            ArrayList viewsToDelete = new ArrayList();
            while (objects.MoveNext())
            {
                Tekla.Structures.Drawing.View view =
                    objects.Current as Tekla.Structures.Drawing.View;
                if (view != null)
                {
                    viewsToDelete.Add(view);
                }
            }

            for (int i = 0; i < viewsToDelete.Count; i++)
            {
                Tekla.Structures.Drawing.View v =
                    viewsToDelete[i] as Tekla.Structures.Drawing.View;
                if (v != null)
                {
                    v.Delete();
                }
            }

            drawing.Modify();
        }
        catch
        {
            // Nao bloquear se falhar ao remover vistas padrao
        }
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Criar as 4 vistas isometricas com rotacoes
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static bool CreatePerspectiveViews(
        Tekla.Structures.Drawing.Drawing drawing,
        AABB boundingBox,
        string displayName)
    {
        try
        {
            Tekla.Structures.Drawing.ContainerView sheet = drawing.GetSheet();
            if (sheet == null)
            {
                MessageBox.Show("Nao foi possivel obter a folha do desenho.", "Erro",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
                return false;
            }

            // Centro do bounding box ??? origem das vistas (coordenadas do modelo)
            Tekla.Structures.Geometry3d.Point center = new Tekla.Structures.Geometry3d.Point(
                (boundingBox.MinPoint.X + boundingBox.MaxPoint.X) / 2.0,
                (boundingBox.MinPoint.Y + boundingBox.MaxPoint.Y) / 2.0,
                (boundingBox.MinPoint.Z + boundingBox.MaxPoint.Z) / 2.0);

            // Semi-extensoes da peca ??? o AABB da vista e RELATIVO ao viewCS,
            // nao em coordenadas globais do modelo.
            // Usar a semi-diagonal maxima para garantir que a peca fique
            // visivel de qualquer angulo de rotacao.
            double halfX = (boundingBox.MaxPoint.X - boundingBox.MinPoint.X) / 2.0;
            double halfY = (boundingBox.MaxPoint.Y - boundingBox.MinPoint.Y) / 2.0;
            double halfZ = (boundingBox.MaxPoint.Z - boundingBox.MinPoint.Z) / 2.0;
            double maxHalf = halfX;
            if (halfY > maxHalf) maxHalf = halfY;
            if (halfZ > maxHalf) maxHalf = halfZ;
            // Margem extra de 20% para folga visual
            maxHalf = maxHalf * 1.2;
            if (maxHalf < 500.0) maxHalf = 500.0; // minimo 500mm

            AABB localBox = new AABB(
                new Tekla.Structures.Geometry3d.Point(-maxHalf, -maxHalf, -maxHalf),
                new Tekla.Structures.Geometry3d.Point(maxHalf, maxHalf, maxHalf));

            int viewsInserted = 0;

            for (int i = 0; i < 4; i++)
            {
                string viewName = string.Format("Perspectiva {0} - {1}", ROMAN[i], displayName);

                // Calcular sistema de coordenadas rotacionado
                // viewCS: origem no centro da peca (modelo), eixos rotacionados
                CoordinateSystem viewCS = CreateViewRotation(center, Z_ANGLES[i], X_ANGLE);
                // displayCS: mesma rotacao mas origem em (0,0,0) ??? projecao no papel
                CoordinateSystem displayCS = CreateViewRotation(
                    new Tekla.Structures.Geometry3d.Point(0, 0, 0), Z_ANGLES[i], X_ANGLE);

                try
                {
                    // Criar a vista ??? localBox e relativo ao viewCS
                    Tekla.Structures.Drawing.View view = new Tekla.Structures.Drawing.View(
                        sheet, viewCS, displayCS, localBox);

                    view.Name = viewName;

                    if (view.Insert())
                    {
                        viewsInserted++;
                    }
                }
                catch (Exception exView)
                {
                    // Log mas nao abortar ??? tentar as demais vistas
                    System.Diagnostics.Debug.WriteLine(
                        string.Format("Falha ao criar vista {0}: {1}", ROMAN[i], exView.Message));
                }
            }

            // Posicionar vistas automaticamente na folha
            if (viewsInserted > 0)
            {
                try
                {
                    drawing.PlaceViews();
                }
                catch
                {
                    // PlaceViews pode nao estar disponivel em todas as versoes
                    // As vistas ficam inseridas mas podem precisar de posicionamento manual
                }

                drawing.Modify();
            }

            if (viewsInserted == 0) return false;

            if (viewsInserted < 4)
            {
                MessageBox.Show(
                    string.Format("Apenas {0} de 4 vistas foram criadas com sucesso.\nAs demais podem ter falhado por limitacao da API.", viewsInserted),
                    "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }

            return true;
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                string.Format("Erro ao criar as vistas: {0}", ex.Message),
                "Erro", MessageBoxButtons.OK, MessageBoxIcon.Error);
            return false;
        }
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Criar CoordinateSystem para vista isometrica
    //
    // Logica de camera 3D:
    //   - Parte de uma VISTA FRONTAL (olhando ao longo de -Y)
    //     AxisX = (1,0,0) "direita", AxisY = (0,0,1) "cima"
    //   - Rotaciona o azimute (Z) para girar ao redor da peca
    //   - Inclina a elevacao (X) para olhar de cima
    //
    // zAngleDeg: rotacao em torno do eixo Z (azimute)
    // xAngleDeg: rotacao em torno do eixo X (elevacao)
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static CoordinateSystem CreateViewRotation(Tekla.Structures.Geometry3d.Point origin, double zAngleDeg, double xAngleDeg)
    {
        double zRad = zAngleDeg * Math.PI / 180.0;
        double xRad = xAngleDeg * Math.PI / 180.0;

        // AxisX = vetor "Right" da camera
        // Parte de (1,0,0) e gira ao redor de Z pelo azimute
        // Nao e afetado pela elevacao (permanece horizontal)
        double axisXx = Math.Cos(zRad);
        double axisXy = Math.Sin(zRad);
        double axisXz = 0.0;

        // AxisY = vetor "Up" da camera
        // Parte de (0,0,1) e e inclinado pela elevacao
        // Rotacao do Up ao redor do eixo Right:
        //   Up_new = Up * cos(elev) + LookDir * sin(elev)
        //   onde LookDir (antes da elevacao) = (sin(z), -cos(z), 0)
        double axisYx = Math.Sin(zRad) * Math.Sin(xRad);
        double axisYy = -Math.Cos(zRad) * Math.Sin(xRad);
        double axisYz = Math.Cos(xRad);

        Vector axisX = new Vector(axisXx, axisXy, axisXz);
        Vector axisY = new Vector(axisYx, axisYy, axisYz);

        return new CoordinateSystem(origin, axisX, axisY);
    }

    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    // Abrir o desenho no editor
    // ?????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????????
    private static void OpenDrawing(Tekla.Structures.Drawing.Drawing drawing, string displayName)
    {
        try
        {
            Tekla.Structures.Drawing.DrawingHandler drawingHandler =
                new Tekla.Structures.Drawing.DrawingHandler();

            bool opened = drawingHandler.SetActiveDrawing(drawing);

            if (!opened)
            {
                MessageBox.Show(
                    string.Format("O desenho '{0}' foi criado com sucesso mas nao pode ser aberto automaticamente.\nAbra-o pelo Document Manager.", displayName),
                    "Desenho criado", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                string.Format("O desenho foi criado, mas houve erro ao abri-lo:\n{0}\n\nAbra pelo Document Manager.", ex.Message),
                "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }
}

